let estados = flow.get("escenarios") || {
    calor: false,
    humedad: false,
    reservaBaja: false,
    fuga: false,
    escotillaAbierta: false
};

const comando = msg.payload;

if (comando === "reset") {
    estados = {
        calor: false,
        humedad: false,
        reservaBaja: false,
        fuga: false,
        escotillaAbierta: false
    };
}
else if (Object.hasOwn(estados, comando)) {
    estados[comando] = !estados[comando];
}

flow.set("escenarios", estados);

msg.payload = estados;
return msg;

const s = flow.get("escenarios") || {};

msg.topic = "sensor/dht11";
msg.payload = {
    temperature_c: Number((
        s.calor ? 34 + Math.random() : 23 + Math.random() * 3
    ).toFixed(1)),
    humidity_pct: Number((
        s.humedad ? 78 + Math.random() : 50 + Math.random() * 10
    ).toFixed(1))
};

return msg;

const s = flow.get("escenarios") || {};

msg.topic = "sensor/reed";
msg.payload = {
    hatch_state: s.escotillaAbierta ? "open" : "closed"
};

return msg;

const s = flow.get("escenarios") || {};

msg.topic = "sensor/ultrasonico";
msg.payload = {
    tank_level_pct: Number((
        s.reservaBaja ? 45 + Math.random() * 5 :
            75 + Math.random() * 10
    ).toFixed(1))
};

return msg;

const s = flow.get("escenarios") || {};

msg.topic = "sensor/fuga";
msg.payload = {
    leak_detected: !!s.fuga
};

return msg;

let datos = flow.get("sensores") || {};

switch (msg.topic) {
    case "sensor/dht11":
        datos.ambiente = msg.payload;
        break;

    case "sensor/ultrasonico":
        datos.nivel = msg.payload.tank_level_pct;
        break;

    case "sensor/fuga":
        datos.fuga = msg.payload.leak_detected;
        break;

    case "sensor/reed":
        datos.acceso = msg.payload.hatch_state;
        break;

    default:
        return null;
}

flow.set("sensores", datos);

const timestamp = new Date().toISOString();
const salida = [null, null, null];

if (msg.topic === "sensor/dht11") {
    salida[0] = {
        topic: "bunker/g5/telemetria/ambiente",
        payload: {
            device_id: "esp32-env-01",
            ...datos.ambiente,
            timestamp
        }
    };
}

if (
    msg.topic === "sensor/fuga" &&
    typeof datos.nivel === "number" &&
    typeof datos.fuga === "boolean"

) {
    salida[1] = {
        topic: "bunker/g5/telemetria/hidrico",
        payload: {
            device_id: "esp32-water-01",
            tank_level_pct: datos.nivel,
            leak_detected: datos.fuga,
            timestamp
        }
    };
}

if (msg.topic === "sensor/reed") {
    salida[2] = {
        topic: "bunker/g5/telemetria/acceso",
        payload: {
            device_id: "esp32-env-01",
            hatch_state: datos.acceso,
            timestamp
        }
    };
}

return salida;

if (msg.topic !== "bunker/g5/telemetria/hidrico") {
    return null;
}

const p = msg.payload;

if (typeof p.leak_detected !== "boolean") {
    return null;
}

const fuga = p.leak_detected;
const anterior = context.get("fugaAnterior");

// Solo publicar cuando el estado cambia
if (anterior === fuga) {
    return null;
}

context.set("fugaAnterior", fuga);

msg.topic = "bunker/g5/alerta/fuga";

msg.payload = {
    device_id: p.device_id || "esp32-water-01",
    severity: fuga ? "CRITICAL" : "INFO",
    event: fuga
        ? "WATER_LEAK_TRIGGERED"
        : "WATER_LEAK_CLEARED",
    active: fuga,
    timestamp: new Date().toISOString()
};

return msg;

if (msg.topic !== "bunker/g5/telemetria/acceso") {
    return null;
}

const p = msg.payload;
const estado = p.hatch_state;

if (estado !== "open" && estado !== "closed") {
    return null;
}

const armado = flow.get("modoProteccion") === true;
const anterior = context.get("estadoAnterior");
let alarmaActiva = context.get("alarmaActiva") === true;

context.set("estadoAnterior", estado);

// Activar alarma por apertura bajo protección
if (
    armado &&
    estado === "open" &&
    anterior !== "open" &&
    !alarmaActiva
) {
    alarmaActiva = true;
    context.set("alarmaActiva", true);

    msg.topic = "bunker/g5/alerta/escotilla";
    msg.payload = {
        device_id: p.device_id || "esp32-env-01",
        severity: "WARNING",
        event: "UNAUTHORIZED_HATCH_OPEN",
        active: true,
        timestamp: new Date().toISOString()
    };
    return msg;
}

// Resolver alarma cuando se cierra la escotilla
if (estado === "closed" && alarmaActiva) {
    context.set("alarmaActiva", false);

    msg.topic = "bunker/g5/alerta/escotilla";
    msg.payload = {
        device_id: p.device_id || "esp32-env-01",
        severity: "INFO",
        event: "HATCH_ALERT_CLEARED",
        active: false,
        timestamp: new Date().toISOString()
    };
    return msg;
}

return null;

if (msg.topic !== "bunker/g5/telemetria/hidrico") {
    return null;
}

const p = msg.payload;
const nivel = p.tank_level_pct;

if (
    typeof nivel !== "number" ||
    !Number.isFinite(nivel) ||
    nivel < 0 ||
    nivel > 100
) {
    return null;
}

const alerta = nivel < 60;
const anterior = context.get("reservaBajaAnterior");

if (anterior === alerta) {
    return null;
}

context.set("reservaBajaAnterior", alerta);

msg.topic = "bunker/g5/alerta/hidrico";

msg.payload = {
    device_id: p.device_id || "esp32-water-01",
    severity: alerta ? "WARNING" : "INFO",
    event: alerta
        ? "LOW_WATER_LEVEL"
        : "WATER_LEVEL_RECOVERED",
    tank_level_pct: nivel,
    active: alerta,
    timestamp: new Date().toISOString()
};

return msg;

if (msg.payload === "ARM") {
    flow.set("modoProteccion", true);
    node.status({
        fill: "green",
        shape: "dot",
        text: "Protección activada"
    });
}

if (msg.payload === "DISARM") {
    flow.set("modoProteccion", false);
    node.status({
        fill: "grey",
        shape: "ring",
        text: "Protección desactivada"
    });
}

return null;

/*
 * BunkerOS - Motor de control Cloud
 *
 * Salida 1: eventos de actuadores
 * Salida 2: estados de actuadores
 *
 * Reglas:
 * Ventilador: ON >=30 C; OFF <=27 C
 * Valvula: CLOSED >=100%; OPEN <80%
 * Fuga: obliga a cerrar la valvula
 * Control manual: ON/OFF, OPEN/CLOSE y AUTO
 */

let p = msg.payload;

if (typeof p === "string") {
    try {
        p = JSON.parse(p);
    } catch (e) {
        node.warn("JSON no valido");
        return null;
    }
}

if (!p || typeof p !== "object" || Array.isArray(p)) {
    return null;
}

// Estado persistente dentro del nodo
let s = context.get("controlBunker") || {
    temperatura: null,
    nivel: null,
    fuga: null,
    fan: "OFF",
    valve: "OPEN",
    fanMode: "AUTO",
    valveMode: "AUTO",
    fanRequest: null,
    valveRequest: null,
    initializedFan: false,
    initializedValve: false
};

const anteriorFan = s.fan;
const anteriorValve = s.valve;

let motivoFan = "AUTO";
let motivoValve = "AUTO";
let resultadoComando = null;

// 1. RECIBIR TELEMETRIA
if (msg.topic === "bunker/g5/telemetria/ambiente") {
    if (typeof p.temperature_c !== "number" ||
        !Number.isFinite(p.temperature_c)) return null;

    s.temperatura = p.temperature_c;
}

else if (msg.topic === "bunker/g5/telemetria/hidrico") {
    if (typeof p.tank_level_pct !== "number" ||
        !Number.isFinite(p.tank_level_pct) ||
        p.tank_level_pct < 0 ||
        p.tank_level_pct > 100 ||
        typeof p.leak_detected !== "boolean") return null;

    s.nivel = p.tank_level_pct;
    s.fuga = p.leak_detected;
}

// 2. RECIBIR COMANDOS MANUALES
else if (msg.topic === "bunker/g5/control/ventilacion") {
    if (p.target !== "fan" ||
        !["ON", "OFF", "AUTO"].includes(p.action)) return null;

    s.fanMode = p.action === "AUTO" ? "AUTO" : "MANUAL";
    s.fanRequest = p.action === "AUTO" ? null : p.action;
    resultadoComando = "ACCEPTED";
}

else if (msg.topic === "bunker/g5/control/valvula") {
    if (p.target !== "valve" ||
        !["OPEN", "CLOSE", "AUTO"].includes(p.action)) return null;

    if (p.action === "OPEN" && s.fuga !== false) {
        resultadoComando = "REJECTED_LEAK_OR_UNKNOWN";
    } else {
        s.valveMode = p.action === "AUTO" ? "AUTO" : "MANUAL";
        s.valveRequest = p.action === "AUTO" ? null : p.action;
        resultadoComando = "ACCEPTED";
    }
}

else {
    return null;
}

// 3. CONTROL DE VENTILACION
if (s.fanMode === "MANUAL") {
    s.fan = s.fanRequest;
    motivoFan = "MANUAL";
}
else if (s.temperatura !== null) {
    if (s.temperatura >= 30) s.fan = "ON";
    else if (s.temperatura <= 27) s.fan = "OFF";

    motivoFan = "TEMPERATURE_CONTROL";
}

// 4. CONTROL HIDRICO
// La seguridad tiene prioridad sobre las ordenes.
if (s.fuga === true) {
    s.valve = "CLOSED";
    motivoValve = "LEAK_SAFETY";
}
else if (s.fuga === false) {
    if (s.valveMode === "MANUAL") {
        s.valve = s.valveRequest === "CLOSE" ? "CLOSED" : "OPEN";
        motivoValve = "MANUAL";
    }
    else if (s.nivel !== null) {
        if (s.nivel >= 100) {
            s.valve = "CLOSED";
            motivoValve = "TANK_FULL";
        }
        else if (s.nivel < 80) {
            s.valve = "OPEN";
            motivoValve = "TANK_LOW";
        }
    }
}
else {
    // Sin dato valido del detector de fuga:
    // no permitir una apertura insegura.
    s.valve = "CLOSED";
    motivoValve = "LEAK_STATUS_UNKNOWN";
}

// Guardar estado
context.set("controlBunker", s);

const timestamp = new Date().toISOString();
let eventos = [];

// 5. EVENTOS DE CAMBIO DE ESTADO
if (s.temperatura !== null) {
    if (s.initializedFan && anteriorFan !== s.fan) {
        eventos.push({
            topic: "bunker/g5/evento/ventilacion",
            payload: {
                device_id: "esp32-env-01",
                event: s.fan === "ON" ? "FAN_ON" : "FAN_OFF",
                reason: motivoFan,
                timestamp
            }
        });
    }
    s.initializedFan = true;
}

if (s.nivel !== null && s.fuga !== null) {
    if (s.initializedValve && anteriorValve !== s.valve) {
        eventos.push({
            topic: "bunker/g5/evento/hidrico",
            payload: {
                device_id: "esp32-water-01",
                event: s.valve === "OPEN" ? "VALVE_OPENED" : "VALVE_CLOSED",
                reason: motivoValve,
                tank_level_pct: s.nivel,
                timestamp
            }
        });
    }
    s.initializedValve = true;
}

context.set("controlBunker", s);

// 6. PUBLICAR ESTADOS
const estado = {
    topic: "bunker/g5/estado/actuadores",
    payload: {
        fan_state: s.fan,
        valve_state: s.valve,
        fan_mode: s.fanMode,
        valve_mode: s.valveMode,
        command_result: resultadoComando,
        simulated: true,
        timestamp
    }
};

// Primera salida: eventos (puede haber varios)
// Segunda salida: estado actual
return [eventos.length ? eventos : null, estado];

const ordenes = {
    FAN_ON: [
        "bunker/g5/control/ventilacion",
        "fan", "ON"
    ],
    FAN_OFF: [
        "bunker/g5/control/ventilacion",
        "fan", "OFF"
    ],
    FAN_AUTO: [
        "bunker/g5/control/ventilacion",
        "fan", "AUTO"
    ],
    VALVE_OPEN: [
        "bunker/g5/control/valvula",
        "valve", "OPEN"
    ],
    VALVE_CLOSE: [
        "bunker/g5/control/valvula",
        "valve", "CLOSE"
    ],
    VALVE_AUTO: [
        "bunker/g5/control/valvula",
        "valve", "AUTO"
    ]
};

const orden = ordenes[msg.payload];

if (!orden) return null;

msg.topic = orden[0];

msg.payload = {
    target: orden[1],
    action: orden[2],
    requested_by: "node_red_test",
    timestamp: new Date().toISOString()
};

return msg;
